-- Where a quiz's questions came from: NurSet's built-in question bank, or
-- generated by the AI (Gemini). Used to enforce the daily AI quiz limit.
ALTER TABLE quizzes
    ADD COLUMN source TEXT NOT NULL DEFAULT 'bank' CHECK (source IN ('bank', 'ai'));
CREATE INDEX quizzes_user_source_idx ON quizzes (user_id, source, created_at);
